46	{
47	    auto builder = OpBuilder::atBlockBegin(&op.getFunctionBody().front());
48	    for (unsigned i = 0; i < op.getNumArguments(); i++) {
49	        op.setArgAttr(
50	            i, emitasc::attr::kernelArg,
51	            builder.getAttr<emitasc::KernelArgumentAttr>(emitasc::KernelArgument::Explicit));
52	    }
53	    auto as = builder.getI64IntegerAttr(static_cast<int64_t>(ascendc::AddressSpace::gm));
54	    auto loc = builder.getUnknownLoc();
55	    auto fftsAddr = appendKernelArgument(
56	        op, emitasc::KernelArgument::FftsAddr, "ffts_addr",
57	        MemRefType::get(ShapedType::kDynamic, builder.getIntegerType(64, false), AffineMap(), as));
58	    builder.create<ascendc::SetFftsBaseAddrOp>(loc, fftsAddr);
59	    bool hasMatmul = op.walk([](ascendc::RegistMatmulObjOp) { return WalkResult::interrupt(); }).wasInterrupted();
60	    bool matmulCubeOnly = op->getParentOfType<ModuleOp>()->hasAttrOfType<UnitAttr>(ascendc::attr::matmulCubeOnly);
61	    if (hasMatmul && !matmulCubeOnly) {
62	        Value cond = builder.create<ascendc::AscendIsAICOp>(loc, builder.getI1Type());
63	        auto ifOp = builder.create<scf::IfOp>(loc, cond, false);
64	        builder.setInsertionPointToStart(ifOp.thenBlock());
65	        Value flag = builder.create<arith::ConstantOp>(loc, builder.getI64IntegerAttr(0xf21));
66	        builder.create<ascendc::FftsCrossCoreSyncOp>(loc, ascendc::Pipe::PIPE_MTE3, flag);
